coding.solution:
def timer_range(kind, **cfg):
    if kind == 'constant':
        return (cfg['delay'], cfg['delay'])
    if kind == 'uniform':
        return (cfg['offset'], cfg['offset'] + cfg['random_max'])
    if kind == 'poisson':
        return (cfg['offset'], None)
    raise ValueError(kind)

